CREATE TYPE "public"."coin_reason" AS ENUM('quiz_completed', 'flashcard_reviewed', 'task_completed', 'mission_mock_completed', 'stone_purchased', 'legacy_rewards');--> statement-breakpoint
CREATE TYPE "public"."stone_tier" AS ENUM('crystal', 'semi_precious', 'precious', 'legendary');--> statement-breakpoint
CREATE TABLE "coin_ledger" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"workspace_id" uuid NOT NULL,
	"user_id" uuid NOT NULL,
	"amount" integer NOT NULL,
	"reason" "coin_reason" NOT NULL,
	"subject_id" text,
	"idempotency_key" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "coin_ledger_amount_sign" CHECK (("coin_ledger"."amount" < 0) = ("coin_ledger"."reason" = 'stone_purchased') and "coin_ledger"."amount" <> 0)
);
--> statement-breakpoint
CREATE TABLE "stone_ownership" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"workspace_id" uuid NOT NULL,
	"user_id" uuid NOT NULL,
	"stone_slug" text NOT NULL,
	"ledger_entry_id" uuid NOT NULL,
	"acquired_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE "stones" (
	"slug" text PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"family" text NOT NULL,
	"formula" text NOT NULL,
	"color" text NOT NULL,
	"hardness" text NOT NULL,
	"origin" text NOT NULL,
	"fact" text NOT NULL,
	"lore" text NOT NULL,
	"tier" "stone_tier" NOT NULL,
	"price" integer NOT NULL,
	"position" integer NOT NULL,
	CONSTRAINT "stones_price_positive" CHECK ("stones"."price" > 0)
);
--> statement-breakpoint
-- The retired reward system's points become coins, 1:1, once per person: the
-- sum of their reward_ledger points (focus, quartz, learning and stone awards
-- alike), written as one legacy_rewards row. Rows with no person carried no
-- balance and are dropped with the table.
SELECT "workspace_id", "user_id", sum("points")::int, 'legacy_rewards', NULL, 'legacy_rewards'
FROM "reward_ledger"
WHERE "user_id" IS NOT NULL
GROUP BY "workspace_id", "user_id"
HAVING sum("points") > 0;--> statement-breakpoint
-- Foundry stone proposals can no longer be applied; close any still waiting.
UPDATE "action_proposals" SET "status" = 'cancelled', "updated_at" = now()
WHERE "capability" = 'stones.foundry.create' AND "status" = 'pending';--> statement-breakpoint
