INSERT INTO "coin_ledger" ("workspace_id", "user_id", "amount", "reason", "subject_id", "idempotency_key")
INSERT INTO "stones" ("slug", "name", "family", "formula", "color", "hardness", "origin", "fact", "lore", "tier", "price", "position") VALUES
('diamond', 'Diamond', 'Native element (carbon)', 'C', 'Colorless; rarely yellow, pink, blue', '10', 'South Africa, Botswana, Russia (Yakutia)', 'The hardest natural mineral, diamond is pure carbon crystallized over 150 km deep and carried up in kimberlite eruptions.', 'Ancient Greeks called it adamas, ''unconquerable'', and medieval tradition held that it gave its wearer courage in battle.', 'legendary', 1500, 1),
('gold', 'Gold', 'Native element', 'Au', 'Rich metallic yellow', '2.5–3', 'Victoria (Australia), California (USA), Klondike (Canada)', 'Gold is so malleable that a single gram can be beaten into a translucent sheet about one square meter in area.', 'In Inca tradition gold was called the ''sweat of the sun'', and alchemists long chased it as the most perfect of metals.', 'legendary', 1200, 2),
('painite', 'Painite', 'Borate', 'CaZrAl₉O₁₅(BO₃)', 'Brownish red to orange-red', '8', 'Mogok (Myanmar)', 'Recognized in 1957, painite was long called the rarest gem mineral; only a few crystals were known until new Myanmar finds in the 2000s.', 'With no ancient legends of its own, modern collectors treat painite as a token of rarity and of patience rewarded.', 'precious', 600, 3),
('musgravite', 'Musgravite', 'Oxide (taaffeite group)', 'Be(Mg,Fe,Zn)₂Al₆O₁₂', 'Grayish green to purple', '8–8.5', 'Musgrave Ranges (Australia), Sri Lanka, Myanmar', 'First described in 1967 from Australia''s Musgrave Ranges, musgravite was not seen as a faceted gem until 1993.', 'Too young for myth, it is cherished in collector circles as a talisman of the unexpected find.', 'precious', 575, 4),
('red-beryl', 'Red Beryl', 'Beryl (cyclosilicate)', 'Be₃Al₂Si₆O₁₈', 'Raspberry to purplish red', '7.5–8', 'Wah Wah Mountains, Utah (USA)', 'Gem red beryl comes almost solely from Utah''s Wah Wah Mountains; its color comes from trace manganese, and crystals are tiny.', 'Once sold as ''red emerald'', it carries a modern crystal tradition as the beryl of passion and courage.', 'precious', 550, 5),
('grandidierite', 'Grandidierite', 'Borosilicate', '(Mg,Fe)Al₃(BO₃)(SiO₄)O₂', 'Bluish green to greenish blue', '7–7.5', 'Madagascar, Sri Lanka', 'Named in 1902 for French explorer Alfred Grandidier, transparent gem-quality grandidierite was almost unknown until a 2014 find in Madagascar.', 'In modern gem lore its sea-glass blue is linked to calm and clarity, a tradition only decades old.', 'precious', 525, 6),
('padparadscha-sapphire', 'Padparadscha Sapphire', 'Corundum', 'Al₂O₃', 'Pinkish orange, like a sunset or lotus', '9', 'Sri Lanka, Madagascar, Tanzania', 'Its name comes from the Sinhalese word for the lotus blossom, and only a narrow blend of pink and orange earns it.', 'Sri Lankan tradition likens its sunset hue to the sacred lotus, a symbol of purity and spiritual awakening.', 'precious', 525, 7),
('alexandrite', 'Alexandrite', 'Chrysoberyl', 'BeAl₂O₄', 'Green in daylight, red-purple in incandescent light', '8.5', 'Ural Mountains (Russia), Brazil, Sri Lanka', 'Chromium makes it look green by daylight and raspberry red by candlelight; it was found in Russia''s Urals in the 1830s.', 'Legend says it was named for the future Tsar Alexander II, its red and green echoing imperial Russia''s military colors.', 'precious', 500, 8),
('paraiba-tourmaline', 'Paraíba Tourmaline', 'Tourmaline (elbaite)', 'Na(Li,Al)₃Al₆(Si₆O₁₈)(BO₃)₃(OH)₄', 'Neon electric blue to green', '7–7.5', 'Paraíba (Brazil), Nigeria, Mozambique', 'Found in Brazil''s Paraíba state in the late 1980s, its neon glow comes from copper, an element rarely found in tourmaline.', 'Modern gem lore calls it the stone of tropical lagoons, traditionally linked to calm, clear seas.', 'precious', 500, 9),
('ruby', 'Ruby', 'Corundum', 'Al₂O₃', 'Pinkish red to deep ''pigeon''s blood'' red', '9', 'Mogok (Myanmar), Mozambique, Thailand', 'Chromium gives ruby its red and a strong red fluorescence that makes the finest Burmese stones seem to glow from within.', 'Sanskrit texts called it ratnaraj, ''king of gems'', and Burmese warriors are said to have set rubies under their skin for invincibility.', 'precious', 500, 10),
('jadeite', 'Jadeite', 'Pyroxene', 'NaAlSi₂O₆', 'Emerald green; also lavender, white, black', '6.5–7', 'Hpakant (Myanmar), Guatemala, Itoigawa (Japan)', 'Interlocking pyroxene crystals make jadeite remarkably tough; vivid ''imperial'' green jadeite is among the costliest gems on Earth.', 'Chinese tradition has long prized jade as the stone of heaven, a symbol of virtue, purity and long life.', 'precious', 475, 11),
('benitoite', 'Benitoite', 'Cyclosilicate', 'BaTiSi₃O₉', 'Sapphire blue to violet blue', '6–6.5', 'San Benito County, California (USA)', 'Gem benitoite comes almost only from one California mine; it glows bright blue under shortwave UV and is California''s state gem.', 'Collector tradition holds it a lucky stone, since a single source makes every crystal a fortunate find.', 'precious', 450, 12),
('black-opal', 'Black Opal', 'Opal (hydrated silica mineraloid)', 'SiO₂·nH₂O', 'Dark body with flashing rainbow play-of-color', '5.5–6.5', 'Lightning Ridge, New South Wales (Australia)', 'Black opal''s dark body tone makes its play-of-color blaze, and Lightning Ridge in Australia is its classic source.', 'A widely retold Aboriginal Australian legend says opals formed where a rainbow touched the earth.', 'precious', 450, 13),
('emerald', 'Emerald', 'Beryl (cyclosilicate)', 'Be₃Al₂Si₆O₁₈', 'Bluish green to pure green', '7.5–8', 'Colombia (Muzo), Zambia, Brazil', 'Most emeralds hold inclusions that gem traders call jardin, French for ''garden''; chromium and vanadium give their green.', 'Romans held emerald restful to tired eyes, and the emperor Nero is said to have watched gladiators through one.', 'precious', 450, 14),
('blue-sapphire', 'Blue Sapphire', 'Corundum', 'Al₂O₃', 'Cornflower to deep royal blue', '9', 'Sri Lanka, Kashmir (India), Madagascar', 'Iron and titanium traces give sapphire its blue; corundum in every color except red is called sapphire.', 'Medieval clergy wore sapphires as a symbol of heaven, and kings believed they guarded against envy and harm.', 'precious', 425, 15),
('demantoid-garnet', 'Demantoid Garnet', 'Garnet (andradite)', 'Ca₃Fe₂(SiO₄)₃', 'Vivid grass green to yellowish green', '6.5–7', 'Ural Mountains (Russia), Namibia, Madagascar', 'Its dispersion exceeds diamond''s, and Russian stones often hold golden ''horsetail'' inclusions of chrysotile.', 'Old garnet lore held that travelers carrying one were protected on the road, a belief jewelers extended to this rare green.', 'precious', 400, 16),
('star-sapphire', 'Star Sapphire', 'Corundum', 'Al₂O₃', 'Grey-blue to blue with a six-rayed star', '9', 'Sri Lanka, Myanmar, Thailand', 'Fine rutile needles inside the crystal reflect light into a six-rayed star that glides across the domed cabochon.', 'Sri Lankan travelers traditionally carried star sapphires as guiding stones, reading the crossing rays as faith, hope and destiny.', 'precious', 375, 17),
('pearl', 'Pearl', 'Organic gem (nacre)', 'Organic: aragonite (CaCO₃) layers bound by conchiolin', 'White, cream, pink, silver, black', '2.5–4.5', 'Persian Gulf, Japan, French Polynesia', 'Natural pearls form when a mollusk coats an irritant in nacre; before cultured pearls, the Persian Gulf supplied the finest.', 'Old legends from many lands describe pearls as tears of the moon or drops of dew caught by shellfish.', 'precious', 350, 18),
('tanzanite', 'Tanzanite', 'Epidote group (zoisite)', 'Ca₂Al₃(SiO₄)(Si₂O₇)O(OH)', 'Violet-blue, strongly pleochroic', '6–7', 'Merelani Hills (Tanzania)', 'Found in 1967 in a few square kilometers near Mount Kilimanjaro, most tanzanite is gently heated to bring out its blue-violet.', 'A modern East African gift tradition presents tanzanite at a child''s birth as a token of new beginnings.', 'precious', 325, 19),
('platinum', 'Platinum', 'Native element', 'Pt', 'Steel grey to silvery white', '4–4.5', 'Ural Mountains (Russia), Chocó (Colombia), South Africa', 'Spanish colonists in Colombia called it platina, ''little silver'', and once dismissed it as a nuisance in their gold washings.', 'In modern jewelry tradition, platinum''s endurance made it the classic symbol of lasting love and commitment.', 'precious', 300, 20),
('hauyne', 'Haüyne', 'Feldspathoid (sodalite group)', 'Na₃Ca(Si₃Al₃)O₁₂(SO₄)', 'Intense electric blue', '5.5–6', 'Eifel (Germany)', 'Haüyne crystals from Germany''s volcanic Eifel are tiny; faceted stones over one carat are extraordinarily rare.', 'Crystal enthusiasts traditionally link its volcanic blue with clear expression, much like its cousin lapis.', 'semi_precious', 200, 21),
('imperial-topaz', 'Imperial Topaz', 'Topaz (nesosilicate)', 'Al₂SiO₄(F,OH)₂', 'Golden orange to pinkish orange', '8', 'Ouro Preto (Brazil)', 'Topaz has perfect cleavage, so one sharp knock can split even a flawless crystal cleanly in two.', 'Legend says the name ''imperial'' honored royalty, whether Russia''s tsars or Brazil''s emperor Dom Pedro II.', 'semi_precious', 200, 22),
('jeremejevite', 'Jeremejevite', 'Borate', 'Al₆(BO₃)₅(F,OH)₃', 'Pale cornflower blue to colorless', '6.5–7.5', 'Erongo (Namibia), Siberia (Russia)', 'First found in Siberia in 1883, its best gem crystals came much later from Namibia''s Erongo Mountains as slim blue prisms.', 'Lacking ancient legend, it is prized among collectors as an emblem of rare and clear-sighted taste.', 'semi_precious', 200, 23),
('pezzottaite', 'Pezzottaite', 'Beryl group (cyclosilicate)', 'Cs(Be₂Li)Al₂Si₆O₁₈', 'Raspberry red to pink', '8', 'Madagascar, Afghanistan', 'Identified in 2003, this cesium-rich cousin of beryl was first sold in Madagascar as ''raspberyl'' or red beryl.', 'So new that its lore is still being written, collectors keep it as a keepsake of a modern discovery.', 'semi_precious', 200, 24),
('pink-sapphire', 'Pink Sapphire', 'Corundum', 'Al₂O₃', 'Light pastel to hot pink', '9', 'Madagascar, Sri Lanka, Myanmar', 'Pink sapphire is colored by the same chromium as ruby, and labs still debate where pink ends and red begins.', 'In modern gem tradition, pink sapphire is a stone of compassion and a favored alternative engagement gem.', 'semi_precious', 200, 25),
('cats-eye-chrysoberyl', 'Cat''s Eye Chrysoberyl', 'Chrysoberyl', 'BeAl₂O₄', 'Honey yellow to greenish with a sharp silky eye', '8.5', 'Sri Lanka, Brazil, India', 'Parallel silk needles create a sharp line of light; gemologists reserve the unqualified name ''cat''s eye'' for chrysoberyl.', 'In Sri Lankan and Indian tradition it was worn to ward off evil, and Vedic astrology links it to the shadow planet Ketu.', 'semi_precious', 190, 26),
('spinel', 'Spinel', 'Spinel (oxide)', 'MgAl₂O₄', 'Red, pink, blue, violet', '7.5–8', 'Mogok (Myanmar), Mahenge (Tanzania), Tajikistan', 'The ''Black Prince''s Ruby'' in Britain''s Imperial State Crown is actually a large red spinel.', 'Medieval lapidaries, unaware it differed from ruby, prized red ''balas'' stones from Badakhshan as royal talismans.', 'semi_precious', 190, 27),
('tsavorite-garnet', 'Tsavorite Garnet', 'Garnet (grossular)', 'Ca₃Al₂(SiO₄)₃', 'Vivid emerald green', '7–7.5', 'Kenya, Tanzania', 'Discovered in East Africa in the late 1960s, it was named by Tiffany & Co. after Kenya''s Tsavo National Park.', 'Modern gem lore links its fresh green to vitality and growth, echoing the savanna that lent it its name.', 'semi_precious', 190, 28),
('aquamarine', 'Aquamarine', 'Beryl (cyclosilicate)', 'Be₃Al₂Si₆O₁₈', 'Pale sky blue to blue-green', '7.5–8', 'Brazil, Madagascar, Pakistan', 'Iron gives aquamarine its blue; a Brazilian crystal found in 1910 weighed about 110 kg, one of the largest gem crystals known.', 'Sailors traditionally carried aquamarine, Latin for ''sea water'', as a charm for calm seas and safe voyages.', 'semi_precious', 180, 29),
('clinohumite', 'Clinohumite', 'Humite group (nesosilicate)', '(Mg,Fe)₉(SiO₄)₄(F,OH)₂', 'Bright orange to brownish yellow', '6', 'Pamir Mountains (Tajikistan), Siberia (Russia), Tanzania', 'Gem clinohumite was virtually unknown until a 1983 find in the Pamir Mountains, later joined by Siberia and Tanzania.', 'Modern crystal lore, with no old tales to draw on, ties its fiery orange to motivation and courage.', 'semi_precious', 180, 30),
('sapphirine', 'Sapphirine', 'Inosilicate', '(Mg,Al)₈(Al,Si)₆O₂₀', 'Blue, violet, pink', '7.5', 'Sri Lanka, Madagascar, Tanzania', 'Named for its sapphire-like blue, it is unrelated to corundum and forms in very high-temperature metamorphic rocks.', 'Among gem collectors it is traditionally offered as a quiet rarity, a stone for those who know where to look.', 'semi_precious', 180, 31),
('yellow-sapphire', 'Yellow Sapphire', 'Corundum', 'Al₂O₃', 'Lemon to canary yellow', '9', 'Sri Lanka, Madagascar, Thailand', 'Traces of iron give yellow sapphire its color, and Sri Lanka has yielded fine canary stones for centuries.', 'In Vedic astrology tradition, yellow sapphire (pukhraj) is the gem of Jupiter, worn for wisdom and prosperity.', 'semi_precious', 180, 32),
('boulder-opal', 'Boulder Opal', 'Opal (hydrated silica mineraloid)', 'SiO₂·nH₂O', 'Rainbow opal veins in brown ironstone', '5.5–6.5', 'Queensland (Australia)', 'Boulder opal forms in cracks of ironstone concretions, so it is cut with the brown host rock left as a natural backing.', 'Victorian superstition branded opals unlucky after a Walter Scott novel, a belief Queen Victoria herself ignored.', 'semi_precious', 170, 33),
('euclase', 'Euclase', 'Beryllium silicate (nesosilicate)', 'BeAlSiO₄(OH)', 'Colorless, pale blue to sea green', '7.5', 'Minas Gerais (Brazil), Colombia, Zimbabwe', 'Its name means ''easily broken'' in Greek, a nod to perfect cleavage that makes faceting it a real challenge.', 'Collector tradition treats euclase as a lesson in gentleness, its fragile cleavage a reminder to handle beauty with care.', 'semi_precious', 170, 34),
('opal', 'Opal', 'Opal (hydrated silica mineraloid)', 'SiO₂·nH₂O', 'White to light body with rainbow play-of-color', '5.5–6.5', 'Coober Pedy (Australia), Wollo (Ethiopia), Mexico', 'Play-of-color comes from stacked silica spheres that diffract light like a natural grating.', 'The Roman writer Pliny praised opal for holding the colors of all gems, and Roman tradition made it a token of hope.', 'semi_precious', 170, 35),
('rubellite-tourmaline', 'Rubellite Tourmaline', 'Tourmaline (elbaite)', 'Na(Li,Al)₃Al₆(Si₆O₁₈)(BO₃)₃(OH)₄', 'Pink-red to raspberry red', '7–7.5', 'Brazil, Nigeria, Madagascar', 'The ''Caesar''s Ruby'' pendant in Russia''s old royal treasure is in fact rubellite; manganese gives the red.', 'Crystal lore says rubellite opens the heart and kindles devotion, a stone of warmth in modern tradition.', 'semi_precious', 170, 36),
('sinhalite', 'Sinhalite', 'Borate', 'MgAlBO₄', 'Yellow-brown to greenish brown', '6.5–7', 'Sri Lanka, Myanmar', 'Long mistaken for brown peridot, sinhalite was recognized as a new mineral in 1952 and named after Sri Lanka.', 'Named from Sinhala, Sri Lanka''s old name, it shares the island''s long tradition of gems carried as talismans.', 'semi_precious', 170, 37),
('ammolite', 'Ammolite', 'Organic gem (fossil shell)', 'Organic: aragonite (CaCO₃) from ammonite shell', 'Iridescent red, green, gold and blue', '3.5–4.5', 'Alberta (Canada)', 'Cut from ammonite shells about 70 million years old, gem ammolite comes almost only from Alberta''s Bearpaw Formation.', 'In Blackfoot tradition, ammonite fossils called iniskim, ''buffalo stones'', were kept to call the herds.', 'semi_precious', 160, 38),
('fire-opal', 'Fire Opal', 'Opal (hydrated silica mineraloid)', 'SiO₂·nH₂O', 'Yellow, orange to red, sometimes with play-of-color', '5.5–6.5', 'Querétaro (Mexico), Ethiopia, Brazil', 'Unlike most opal, its glowing body color is the main attraction; many Mexican fire opals show no play-of-color at all.', 'Crystal folklore says fire opal kindles passion and creativity, like a flame held in stone.', 'semi_precious', 160, 39),
('hiddenite', 'Hiddenite', 'Spodumene (pyroxene)', 'LiAlSi₂O₆', 'Pale to emerald green', '6.5–7', 'North Carolina (USA), Afghanistan, Brazil', 'Named for William Hidden, who found it in North Carolina in 1879 while searching for platinum for Thomas Edison.', 'Crystal tradition pairs hiddenite with its pink sibling kunzite, calling the green one a stone of fresh starts.', 'semi_precious', 160, 40),
('indicolite-tourmaline', 'Indicolite Tourmaline', 'Tourmaline (elbaite)', 'Na(Li,Al)₃Al₆(Si₆O₁₈)(BO₃)₃(OH)₄', 'Blue to greenish blue', '7–7.5', 'Brazil, Namibia, Afghanistan', 'Pure blue tourmaline is rare; indicolite is so pleochroic that it can look nearly black viewed down the crystal''s length.', 'Crystal enthusiasts traditionally pair indicolite with calm speech and quiet intuition.', 'semi_precious', 160, 41),
('morganite', 'Morganite', 'Beryl (cyclosilicate)', 'Be₃Al₂Si₆O₁₈', 'Peach to soft pink', '7.5–8', 'Madagascar, Brazil, California (USA)', 'Named in 1911 for banker J.P. Morgan, morganite owes its blush pink to traces of manganese.', 'Modern crystal tradition calls morganite a stone of tender love and gentle compassion.', 'semi_precious', 160, 42),
('phenakite', 'Phenakite', 'Beryllium silicate (nesosilicate)', 'Be₂SiO₄', 'Colorless, pale yellow or pink', '7.5–8', 'Ural Mountains (Russia), Brazil, Madagascar', 'Its name, Greek for ''deceiver'', comes from being mistaken for quartz, though it is harder and far rarer.', 'Some modern crystal circles regard phenakite as a high-energy stone, a recent tradition without ancient roots.', 'semi_precious', 160, 43),
('spessartine-garnet', 'Spessartine Garnet', 'Garnet (spessartine)', 'Mn₃Al₂(SiO₄)₃', 'Vivid orange to reddish orange', '7–7.5', 'Namibia, Nigeria, Madagascar', 'Named for Germany''s Spessart region, it became famous when vivid ''mandarin'' garnets were found in Namibia in 1991.', 'Medieval garnet lore held that a glowing garnet would darken to warn its wearer of coming danger.', 'semi_precious', 160, 44),
('tugtupite', 'Tugtupite', 'Feldspathoid (sodalite group)', 'Na₄AlBeSi₄O₁₂Cl', 'Pink to crimson, deepening in sunlight', '4', 'Ilímaussaq (Greenland), Mont Saint-Hilaire (Canada)', 'Tugtupite is tenebrescent: it deepens from pale pink to crimson in light, then slowly fades again in darkness.', 'A retold Greenlandic legend calls it ''reindeer blood'' and says it glows brighter when lovers think of each other.', 'semi_precious', 160, 45),
('color-change-garnet', 'Color-Change Garnet', 'Garnet (pyrope–spessartine)', '(Mg,Mn)₃Al₂(SiO₄)₃', 'Blue-green in daylight to purple-red in warm light', '7–7.5', 'Bekily (Madagascar), Tanzania, Sri Lanka', 'Traces of vanadium and chromium let some pyrope–spessartine garnets shift color; Madagascar''s Bekily stones even turn blue.', 'Crystal tradition sees color-change gems as symbols of adaptability, their shifting hues mirroring life''s changes.', 'semi_precious', 150, 46),
('diaspore', 'Diaspore', 'Oxide-hydroxide', 'AlO(OH)', 'Kiwi green to pinkish champagne, shifting with light', '6.5–7', 'Muğla Province (Turkey)', 'Gem diaspore from Turkey''s Anatolian mountains changes from green in daylight to pinkish champagne under warm light.', 'Sold under trade names honoring Ottoman sultans, it carries a modern tradition as a stone of transformation.', 'semi_precious', 150, 47),
('kornerupine', 'Kornerupine', 'Borosilicate', 'Mg₃Al₆(Si,Al,B)₅O₂₁(OH)', 'Green to brownish green', '6–7', 'Madagascar, Sri Lanka, Tanzania', 'Named for Danish geologist Andreas Kornerup and first found in Greenland, gem kornerupine flashes green and brown.', 'A collector''s stone with little folklore, it is traditionally gifted among gem lovers as a token of hidden depth.', 'semi_precious', 150, 48),
('red-coral', 'Red Coral', 'Organic gem (coral skeleton)', 'Organic: calcite (CaCO₃) with organic matter', 'Red to salmon pink', '3–4', 'Mediterranean Sea, Japan, Taiwan', 'Precious coral is the branching skeleton of tiny colonial animals; Mediterranean red coral grows very slowly.', 'Romans hung coral on children''s cradles for protection, and Italian folk tradition still uses coral horns as charms.', 'semi_precious', 150, 49),
('titanite', 'Titanite', 'Titanite (nesosilicate)', 'CaTiSiO₅', 'Yellow-green to brownish', '5–5.5', 'Madagascar, Pakistan, Brazil', 'Also called sphene, titanite has more fire than diamond but is soft enough to scratch easily.', 'From sphene, Greek for ''wedge'', comes a crystal tradition tying it to sharp, clear thinking.', 'semi_precious', 150, 50),
('watermelon-tourmaline', 'Watermelon Tourmaline', 'Tourmaline (elbaite)', 'Na(Li,Al)₃Al₆(Si₆O₁₈)(BO₃)₃(OH)₄', 'Pink core with green rim', '7–7.5', 'Brazil, Madagascar, California (USA)', 'Shifting fluid chemistry as the crystal grew left a pink core and green rim, best seen in slices across the prism.', 'Crystal folklore calls watermelon tourmaline a stone of balance, joining heart-pink with nature-green.', 'semi_precious', 150, 51),
('zircon', 'Zircon', 'Zircon (nesosilicate)', 'ZrSiO₄', 'Blue, golden, red-brown, colorless', '6.5–7.5', 'Cambodia, Sri Lanka, Tanzania', 'Zircon grains from Western Australia''s Jack Hills are about 4.4 billion years old, the oldest known pieces of Earth.', 'Medieval tradition held that zircon aided restful sleep and brought honor and wisdom to its wearer.', 'semi_precious', 150, 52),
('cassiterite', 'Cassiterite', 'Oxide (rutile group)', 'SnO₂', 'Brown to yellowish, rarely colorless', '6–7', 'Bolivia, Yunnan (China), Namibia', 'The main ore of tin, cassiterite also has more fire than diamond, though clean gem crystals are rare.', 'Ancient tradition placed the Cassiterides, the fabled ''tin islands'', somewhere off Europe''s Atlantic coast.', 'semi_precious', 140, 53),
('gem-silica', 'Gem Silica', 'Quartz (chalcedony)', 'SiO₂ colored by chrysocolla', 'Vivid blue to blue-green', '6.5–7', 'Arizona (USA), Peru, Taiwan', 'Chalcedony saturated with copper-bearing chrysocolla, gem silica is far harder and rarer than chrysocolla itself.', 'Crystal circles traditionally call it a stone of calm, peaceful communication.', 'semi_precious', 140, 54),
('kunzite', 'Kunzite', 'Spodumene (pyroxene)', 'LiAlSi₂O₆', 'Pale pink to lilac', '6.5–7', 'Afghanistan, Brazil, California (USA)', 'Named for Tiffany gemologist George F. Kunz, kunzite''s pink can fade with long exposure to strong sunlight.', 'Crystal tradition calls kunzite a stone of gentle love, and many wear it close to the heart.', 'semi_precious', 140, 55),
('peridot', 'Peridot', 'Olivine (forsterite)', '(Mg,Fe)₂SiO₄', 'Olive to lime green', '6.5–7', 'Arizona (USA), Pakistan, Myanmar', 'Peridot forms deep in Earth''s mantle and has even been found in meteorites; Egypt''s Zabargad Island was mined for millennia.', 'Ancient Egyptians are said to have called it the ''gem of the sun'', hunting it on Zabargad by night when it glowed.', 'semi_precious', 140, 56),
('turquoise', 'Turquoise', 'Phosphate', 'CuAl₆(PO₄)₄(OH)₈·4H₂O', 'Sky blue to green, often with matrix veins', '5–6', 'Nishapur (Iran), Arizona (USA), Hubei (China)', 'Turquoise has been mined near Nishapur, Iran, for over 2,000 years; copper gives the blue and iron pushes it green.', 'Navajo and other Southwestern traditions treasure turquoise as a protective stone tied to sky and water.', 'semi_precious', 140, 57),
('axinite', 'Axinite', 'Sorosilicate', 'Ca₂(Fe,Mn)Al₂BSi₄O₁₅(OH)', 'Clove brown to violet-brown', '6.5–7', 'Bourg-d''Oisans (France), Pakistan, Russia', 'Its name, from the Greek for ''axe'', describes the wedge-shaped crystals with knife-sharp edges.', 'Crystal tradition links axinite''s blade-like crystals to grounding and steady focus.', 'semi_precious', 130, 58),
('chrome-tourmaline', 'Chrome Tourmaline', 'Tourmaline (dravite)', 'NaMg₃Al₆(Si₆O₁₈)(BO₃)₃(OH)₃(OH)', 'Intense emerald green', '7–7.5', 'Tanzania, Kenya', 'Found in East Africa in the 1960s, its rich green comes from chromium and vanadium rather than iron.', 'Tourmaline''s name is said to come from the Sinhalese ''turmali'', for mixed gem gravels, giving it a many-colored mystique.', 'semi_precious', 130, 59),
('green-tourmaline', 'Green Tourmaline', 'Tourmaline (elbaite)', 'Na(Li,Al)₃Al₆(Si₆O₁₈)(BO₃)₃(OH)₄', 'Mint to forest green', '7–7.5', 'Brazil, Afghanistan, Namibia', 'Dutch traders called warmed tourmaline ''aschentrekker'' because its pyroelectric charge pulled ash from their pipes.', 'Folk tradition names green tourmaline a stone of growth, said to bring luck to gardeners.', 'semi_precious', 130, 60),
('heliodor', 'Heliodor', 'Beryl (cyclosilicate)', 'Be₃Al₂Si₆O₁₈', 'Golden yellow to greenish yellow', '7.5–8', 'Ukraine, Brazil, Namibia', 'Iron gives golden beryl its color, and its name comes from the Greek for ''gift of the sun''.', 'That sunny name inspired a crystal tradition linking heliodor to warmth, confidence and willpower.', 'semi_precious', 130, 61),
('lapis-lazuli', 'Lapis Lazuli', 'Rock (metamorphic)', 'Rock: mostly lazurite, calcite, pyrite', 'Deep royal blue with golden pyrite flecks', '5–5.5', 'Badakhshan (Afghanistan), Chile, Lake Baikal (Russia)', 'Mined in Afghanistan for over 6,000 years, lapis was ground into ultramarine, once a pigment costlier than gold.', 'Ancient Egyptians held lapis to be a stone of the heavens, inlaying it in Tutankhamun''s golden mask.', 'semi_precious', 130, 62),
('nephrite-jade', 'Nephrite Jade', 'Amphibole (tremolite–actinolite)', 'Ca₂(Mg,Fe)₅Si₈O₂₂(OH)₂', 'Spinach green to creamy white', '6–6.5', 'British Columbia (Canada), New Zealand, Xinjiang (China)', 'Felted amphibole fibers make nephrite one of the toughest gem materials; China has carved it for over 7,000 years.', 'Māori tradition treasures pounamu (nephrite) heirlooms, passed down through generations as carriers of ancestral mana.', 'semi_precious', 130, 63),
('rhodolite-garnet', 'Rhodolite Garnet', 'Garnet (pyrope–almandine)', '(Mg,Fe)₃Al₂(SiO₄)₃', 'Raspberry to purplish red', '7–7.5', 'Tanzania, Sri Lanka, North Carolina (USA)', 'First described from North Carolina''s Cowee Valley, its name comes from the Greek for ''rose stone''.', 'Legend says Noah hung a glowing garnet in the ark to light the way through the dark flood.', 'semi_precious', 130, 64),
('sphalerite', 'Sphalerite', 'Sulfide', 'ZnS', 'Honey yellow, orange to red-brown', '3.5–4', 'Picos de Europa (Spain), Mexico, Tennessee (USA)', 'Gem sphalerite has over three times the fire of diamond, but it is far too soft for everyday jewelry.', 'Old German miners called it ''blende'', meaning deceiver, because it looked like lead ore yet yielded no lead.', 'semi_precious', 130, 65),
('sugilite', 'Sugilite', 'Cyclosilicate (milarite group)', 'KNa₂(Fe,Mn,Al)₂Li₃Si₁₂O₃₀', 'Purple to magenta', '5.5–6.5', 'Kalahari Manganese Field (South Africa), Japan', 'Described in Japan in 1976, sugilite became a gem after vivid purple material turned up in a South African manganese mine.', 'In modern crystal lore, sugilite is said to be a stone of spiritual love and gentle protection.', 'semi_precious', 130, 66),
('ametrine', 'Ametrine', 'Quartz (silicate)', 'SiO₂', 'Purple and golden zones in one crystal', '7', 'Anahí mine (Bolivia)', 'Nearly all natural ametrine comes from Bolivia''s Anahí mine, where amethyst and citrine zones grew in a single crystal.', 'Bolivian legend says it reached Europe as a dowry when a conquistador married an Ayoreo princess named Anahí.', 'semi_precious', 120, 67),
('blue-topaz', 'Blue Topaz', 'Topaz (nesosilicate)', 'Al₂SiO₄(F,OH)₂', 'Sky blue to deep London blue', '8', 'Brazil, Nigeria, Sri Lanka', 'Natural blue topaz is usually pale; most vivid blue topaz sold today is colorless topaz that has been irradiated and heated.', 'Medieval lapidaries believed topaz could cool tempers and break enchantments when held in the hand.', 'semi_precious', 120, 68),
('brazilianite', 'Brazilianite', 'Phosphate', 'NaAl₃(PO₄)₂(OH)₄', 'Yellow-green to greenish yellow', '5.5', 'Minas Gerais (Brazil)', 'First mistaken for chrysoberyl, it was described in 1945 from Minas Gerais and named for its homeland.', 'Being a modern find, its lore is young: crystal circles embrace it as a cheerful stone of creativity.', 'semi_precious', 120, 69),
('chrysoprase', 'Chrysoprase', 'Quartz (chalcedony)', 'SiO₂', 'Apple green', '6.5–7', 'Queensland (Australia), Poland, Tanzania', 'Nickel gives chrysoprase its apple green, making it one of the most valuable chalcedony varieties.', 'Legend has it that Alexander the Great wore chrysoprase in his girdle to bring victory in battle.', 'semi_precious', 120, 70),
('larimar', 'Larimar', 'Pectolite (inosilicate)', 'NaCa₂Si₃O₈(OH)', 'Sky blue with white veins', '4.5–5', 'Barahona (Dominican Republic)', 'Larimar is a blue pectolite found only in the Dominican Republic; its name joins ''Larissa'' with mar, Spanish for sea.', 'Caribbean crystal lore calls larimar the ''Atlantis stone'', a modern tradition linking it to the sea.', 'semi_precious', 120, 71),
('mali-garnet', 'Mali Garnet', 'Garnet (grossular–andradite)', 'Ca₃(Al,Fe)₂(SiO₄)₃', 'Yellow-green to honey brown', '7–7.5', 'Kayes region (Mali)', 'Discovered in Mali in 1994, this grossular–andradite blend pairs grossular''s brightness with andradite''s fire.', 'So recently found, it borrows garnet''s old tradition as a traveler''s protective stone.', 'semi_precious', 120, 72),
('moonstone', 'Moonstone', 'Feldspar (orthoclase/adularia)', 'KAlSi₃O₈', 'Colorless to milky white with blue sheen', '6–6.5', 'Sri Lanka, India, Myanmar', 'Its floating glow, called adularescence, comes from light scattering between thin intergrown layers of two feldspars.', 'Hindu mythology tells that moonstone was formed from moonbeams, and in India it is a traditional lovers'' gift.', 'semi_precious', 120, 73),
('pyrope-garnet', 'Pyrope Garnet', 'Garnet (pyrope)', 'Mg₃Al₂(SiO₄)₃', 'Deep blood red', '7–7.5', 'Bohemia (Czech Republic), Arizona (USA), South Africa', 'Bohemian pyrope fueled a 19th-century jewelry craze, and pyropes in kimberlite help prospectors track down diamonds.', 'Bohemian tradition made pyrope, Greek for ''fiery-eyed'', a keepsake of loyalty and lasting friendship.', 'semi_precious', 120, 74),
('sunstone', 'Sunstone', 'Feldspar (plagioclase)', '(Ca,Na)(Al,Si)₄O₈', 'Peach, orange to red with glittering schiller', '6–6.5', 'Oregon (USA), India, Norway', 'Oregon sunstone sparkles from tiny copper platelets, and it became Oregon''s state gem in 1987.', 'A retold Oregon legend says sunstones hold the blood of a wounded warrior, which gave them their red glow.', 'semi_precious', 120, 75),
('almandine-garnet', 'Almandine Garnet', 'Garnet (almandine)', 'Fe₃Al₂(SiO₄)₃', 'Deep red to purplish red', '7–7.5', 'India, Sri Lanka, Brazil', 'The most common garnet, almandine was cut into thin plates for Anglo-Saxon cloisonné like the Sutton Hoo treasures.', 'Medieval Europeans believed garnets glowed in the dark and could guard sleepers against bad dreams.', 'semi_precious', 110, 76),
('amethyst', 'Amethyst', 'Quartz (silicate)', 'SiO₂', 'Pale lilac to deep purple', '7', 'Brazil, Uruguay, Zambia', 'Iron traces plus natural irradiation make amethyst purple, and heating can turn it yellow like citrine.', 'Its name means ''not drunk'' in Greek, and ancient Greeks believed amethyst cups guarded against drunkenness.', 'semi_precious', 110, 77),
('andalusite', 'Andalusite', 'Nesosilicate', 'Al₂SiO₅', 'Brownish green to orange-brown, changing with angle', '6.5–7.5', 'Brazil, Sri Lanka', 'Andalusite shares its formula with kyanite and sillimanite; it forms at lower pressure and flashes green and brown.', 'Its many-sided color play gives it a modern crystal tradition as a stone for seeing all sides of a question.', 'semi_precious', 110, 78),
('charoite', 'Charoite', 'Inosilicate', 'K(Ca,Na)₂Si₄O₁₀(OH,F)·H₂O', 'Lilac to deep purple with swirling silky fibers', '5–6', 'Chara River, Siberia (Russia)', 'Known from a single region near Siberia''s Chara River, charoite was described as a new mineral in 1978.', 'Modern crystal lore calls charoite a stone of transformation, a tradition as young as the mineral itself.', 'semi_precious', 110, 79),
('chrome-diopside', 'Chrome Diopside', 'Pyroxene', 'CaMgSi₂O₆', 'Intense forest green', '5.5–6.5', 'Siberia (Russia), Pakistan', 'Chromium gives it an emerald-like green, but the color is so deep that larger stones can look almost black.', 'Nicknamed ''Siberian emerald'', it is said in crystal folklore to bring vitality and a love of nature.', 'semi_precious', 110, 80),
('danburite', 'Danburite', 'Borosilicate', 'CaB₂Si₂O₈', 'Colorless to pale pink or yellow', '7–7.5', 'Charcas (Mexico), Madagascar, Myanmar', 'Named for Danbury, Connecticut, where it was first found in 1839, its crystals resemble topaz.', 'Crystal tradition holds danburite a stone of serenity, prized for its clear wedge-tipped crystals.', 'semi_precious', 110, 81),
('hessonite-garnet', 'Hessonite Garnet', 'Garnet (grossular)', 'Ca₃Al₂(SiO₄)₃', 'Cinnamon to honey orange', '7–7.5', 'Sri Lanka, India, Madagascar', 'Nicknamed ''cinnamon stone'', hessonite has a swirling, syrupy look caused by tiny included crystals.', 'In Vedic astrology tradition, hessonite (gomed) is the gem of the shadow planet Rahu.', 'semi_precious', 110, 82),
('iolite', 'Iolite', 'Cordierite (cyclosilicate)', '(Mg,Fe)₂Al₄Si₅O₁₈', 'Violet-blue to grey, strongly pleochroic', '7–7.5', 'India, Sri Lanka, Madagascar', 'Turn an iolite and it shifts from violet-blue to pale yellow-grey; the gem trade once sold it as ''water sapphire''.', 'Legend says Viking sailors used thin slices of iolite to find the sun through clouds and fog.', 'semi_precious', 110, 83),
('lazulite', 'Lazulite', 'Phosphate', 'MgAl₂(PO₄)₂(OH)₂', 'Azure to deep blue', '5.5–6', 'Yukon (Canada), Minas Gerais (Brazil), Austria', 'Not to be confused with the lazurite in lapis, lazulite forms sharp blue crystals at Yukon''s Rapid Creek.', 'Its name traces to old words for ''heaven'', giving it a crystal tradition as a stone of skyward thoughts.', 'semi_precious', 110, 84),
('vesuvianite', 'Vesuvianite', 'Sorosilicate', 'Ca₁₀(Mg,Fe)₂Al₄(SiO₄)₅(Si₂O₇)₂(OH)₄', 'Green, yellow-green to brown', '6–7', 'Mount Vesuvius (Italy), Quebec (Canada), Pakistan', 'First described from blocks thrown out by Mount Vesuvius, it is also known as idocrase.', 'Collectors link vesuvianite to its fiery birthplace, traditionally treating it as a stone of inner strength.', 'semi_precious', 110, 85),
('apatite', 'Apatite', 'Phosphate', 'Ca₅(PO₄)₃(F,Cl,OH)', 'Neon blue, green, yellow', '5', 'Madagascar, Brazil, Durango (Mexico)', 'Apatite defines 5 on the Mohs scale, and a form of it is the main mineral in our teeth and bones.', 'Named from a Greek word for ''deceit'' because it mimics other gems, it is linked in crystal lore to motivation.', 'semi_precious', 100, 86),
('citrine', 'Citrine', 'Quartz (silicate)', 'SiO₂', 'Pale yellow to golden orange', '7', 'Brazil, Bolivia, DR Congo', 'Natural citrine is rare; most citrine on the market is heat-treated amethyst that has turned golden.', 'Nicknamed the ''merchant''s stone'', citrine is traditionally kept in cash boxes to invite prosperity.', 'semi_precious', 100, 87),
('goshenite', 'Goshenite', 'Beryl (cyclosilicate)', 'Be₃Al₂Si₆O₁₈', 'Colorless', '7.5–8', 'Brazil, Madagascar, Pakistan', 'German ''Brille'', eyeglasses, comes from beryl, since some early lenses were ground from clear beryl like goshenite.', 'Medieval scryers traditionally gazed into polished clear beryl, hoping to glimpse the future.', 'semi_precious', 100, 88),
('orthoclase', 'Orthoclase', 'Feldspar (orthoclase)', 'KAlSi₃O₈', 'Pale to golden yellow', '6', 'Itrongay (Madagascar)', 'Orthoclase defines 6 on the Mohs scale; transparent yellow gem orthoclase comes chiefly from Madagascar.', 'Crystal enthusiasts traditionally link golden orthoclase with sunny optimism and fresh beginnings.', 'semi_precious', 100, 89),
('scapolite', 'Scapolite', 'Tectosilicate', '(Na,Ca)₄Al₃(Al,Si)₃Si₆O₂₄(Cl,CO₃,SO₄)', 'Yellow, violet, colorless', '5–6', 'Tanzania, Madagascar, Myanmar', 'Scapolite is a series between marialite and meionite; violet cat''s-eye stones from Myanmar are a collector favorite.', 'Crystal folklore calls scapolite a problem-solver''s stone, a modern tradition with no ancient source.', 'semi_precious', 100, 90),
('cavansite', 'Cavansite', 'Phyllosilicate', 'Ca(VO)Si₄O₁₀·4H₂O', 'Vivid electric blue rosettes', '3–4', 'Pune (India), Oregon (USA)', 'Its name comes from calcium, vanadium and silicon, and its best rosettes come from quarries near Pune, India.', 'Crystal lore credits cavansite with lifting creativity, inspired by its startling blue.', 'crystal', 70, 91),
('dioptase', 'Dioptase', 'Cyclosilicate', 'Cu₆Si₆O₁₈·6H₂O', 'Intense emerald green', '5', 'Altyn-Tyube (Kazakhstan), Tsumeb (Namibia), DR Congo', 'Kazakh miners once mistook it for emerald; its name means ''to see through'', for reflections from inner cleavage.', 'Its ''Kazakh emerald'' history inspires a crystal tradition calling dioptase a stone of the heart.', 'crystal', 70, 92),
('iron-meteorite', 'Iron Meteorite', 'Meteorite (iron-nickel)', 'Iron–nickel alloy (kamacite and taenite)', 'Metallic grey with etched crosshatch pattern', '4', 'Gibeon (Namibia), Campo del Cielo (Argentina), Sikhote-Alin (Russia)', 'Etched slices show Widmanstätten patterns, nickel-iron crystals that grew over millions of years of slow cooling.', 'Ancient Egyptians called iron ''metal of heaven'', and Tutankhamun''s dagger was forged from meteoritic iron.', 'crystal', 70, 93),
('moldavite', 'Moldavite', 'Tektite (natural glass)', 'Silica-rich glass from a meteorite impact', 'Forest to olive green', '5.5', 'Bohemia (Czech Republic)', 'Moldavite formed about 15 million years ago when a meteorite struck Germany''s Ries crater, flinging molten glass into Bohemia.', 'Modern crystal lore holds moldavite to be a powerful ''stone of transformation'' from the stars.', 'crystal', 70, 94),
('native-silver', 'Native Silver', 'Native element', 'Ag', 'Bright silver-white, tarnishing black', '2.5–3', 'Kongsberg (Norway), Batopilas (Mexico), Cobalt, Ontario (Canada)', 'Norway''s Kongsberg mines produced famous wire silver, curling strands that grow like hair from the rock.', 'European folklore credits silver with warding off werewolves and evil spirits, as in silver bullet tales.', 'crystal', 70, 95),
('crocoite', 'Crocoite', 'Chromate', 'PbCrO₄', 'Bright orange-red needles', '2.5–3', 'Dundas, Tasmania (Australia)', 'Chromium, now vital to stainless steel, was discovered in 1797 by analyzing crocoite from Siberia.', 'Tasmanians honor crocoite as their island''s mineral emblem, a cherished tradition since 2000.', 'crystal', 65, 96),
('fire-agate', 'Fire Agate', 'Quartz (chalcedony)', 'SiO₂ with layers of iron oxide', 'Brown with iridescent orange, green and gold flashes', '6.5–7', 'Arizona (USA), Mexico', 'Thin layers of iron oxide within the chalcedony diffract light into rainbow fire just below the surface.', 'Crystal folklore says fire agate holds the spirit of flame, a traditional stone of courage.', 'crystal', 65, 97),
('libyan-desert-glass', 'Libyan Desert Glass', 'Natural glass (impactite)', 'Nearly pure amorphous silica glass', 'Pale yellow to golden', '6', 'Great Sand Sea (Egypt, Libya)', 'Formed about 29 million years ago, possibly by a meteorite airburst, this glass is roughly 98% silica.', 'A scarab of it sits in Tutankhamun''s pectoral, giving it a tradition as a sacred solar stone of Egypt.', 'crystal', 65, 98),
('rhodochrosite', 'Rhodochrosite', 'Carbonate', 'MnCO₃', 'Rose pink to cherry red, often banded', '3.5–4', 'Colorado (USA), Capillitas (Argentina), South Africa', 'Colorado''s Sweet Home Mine produced world-famous cherry-red rhombs, and rhodochrosite is Colorado''s state mineral.', 'Argentine legend calls it ''Inca rose'', saying it formed from the blood of ancient Inca rulers.', 'crystal', 65, 99),
('blue-john', 'Blue John', 'Halide (fluorite)', 'CaF₂', 'Purple-blue and yellow bands', '4', 'Castleton, Derbyshire (England)', 'Found only near Castleton in Derbyshire, it has been carved into vases and bowls since the 18th century.', 'Local tradition says the name comes from French ''bleu-jaune'', blue-yellow, though the origin is debated.', 'crystal', 60, 100),
('cuprite', 'Cuprite', 'Oxide', 'Cu₂O', 'Deep crimson red, often dark', '3.5–4', 'Onganja (Namibia), Arizona (USA), Russia', 'Namibia''s Onganja mine yielded cuprite crystals large and clean enough to facet into rare deep red gems.', 'Crystal lore links cuprite''s copper red to vitality and the steady warmth of the hearth.', 'crystal', 60, 101),
('wulfenite', 'Wulfenite', 'Molybdate', 'PbMoO₄', 'Orange, yellow to red tabular plates', '3', 'Red Cloud Mine, Arizona (USA), Mexico, Slovenia', 'Arizona''s Red Cloud Mine is famed for blood-red square plates, and wulfenite is Arizona''s state mineral.', 'Crystal folklore links wulfenite''s glowing thin plates to creativity and manifesting ideas.', 'crystal', 60, 102),
('adamite', 'Adamite', 'Arsenate', 'Zn₂(AsO₄)(OH)', 'Lime green to yellow, glowing under UV', '3.5', 'Mapimí (Mexico), Tsumeb (Namibia), Lavrion (Greece)', 'Mexico''s Ojuela Mine yields lime-green adamite sprays that glow bright green under ultraviolet light.', 'Crystal folklore names adamite a stone of joy, inspired by its cheerful glowing green.', 'crystal', 55, 103),
('azurite', 'Azurite', 'Carbonate', 'Cu₃(CO₃)₂(OH)₂', 'Deep azure blue', '3.5–4', 'Arizona (USA), Morocco, Namibia', 'Azurite slowly alters to green malachite, and pigment ground from it colored many medieval paintings.', 'Crystal folklore names azurite a ''stone of heaven'', said to awaken insight.', 'crystal', 55, 104),
('cobaltoan-calcite', 'Cobaltoan Calcite', 'Carbonate (calcite)', '(Ca,Co)CO₃', 'Hot pink to magenta', '3', 'Katanga (DR Congo), Bou Azzer (Morocco), Spain', 'Traces of cobalt give this calcite its vivid hot pink, often as sparkling crusts in Congo''s copper mines.', 'Crystal tradition makes it a heart stone of self-forgiveness, inspired by its bright pink.', 'crystal', 55, 105),
('hackmanite', 'Hackmanite', 'Feldspathoid (sodalite variety)', 'Na₈Al₆Si₆O₂₄(Cl,S)₂', 'Pale pink to violet; shifts after UV and light', '5.5–6', 'Afghanistan, Mont Saint-Hilaire (Canada), Myanmar', 'This sulfur-bearing sodalite is tenebrescent, changing color after UV exposure and fading back in daylight.', 'Crystal enthusiasts traditionally call hackmanite a ''chameleon stone'' tied to adaptability.', 'crystal', 55, 106),
('herkimer-diamond', 'Herkimer Diamond', 'Quartz (silicate)', 'SiO₂', 'Water-clear', '7', 'Herkimer County, New York (USA)', 'Not diamonds at all, these double-pointed quartz crystals grew in cavities of dolostone about 500 million years old.', 'Crystal tradition calls Herkimers ''attunement stones'', prized for their naturally faceted double points.', 'crystal', 55, 107),
('mimetite', 'Mimetite', 'Arsenate (apatite group)', 'Pb₅(AsO₄)₃Cl', 'Yellow to orange, barrel-shaped crystals', '3.5–4', 'Santa Eulalia (Mexico), Tsumeb (Namibia), Cumbria (England)', 'Its name, from the Greek for ''imitator'', reflects how closely it resembles pyromorphite.', 'Playing on its imitator name, crystal tradition ties mimetite to finding one''s own path.', 'crystal', 55, 108),
('pietersite', 'Pietersite', 'Quartz (silicate)', 'SiO₂ with altered crocidolite fibers', 'Swirling blue, gold and brown shimmer', '7', 'Namibia, China', 'Described by Sid Pieters in 1962 from Namibia, it is a brecciated tiger''s eye whose fibers were folded into swirls.', 'Crystal lore calls pietersite the ''tempest stone'', its swirling shimmer read as storms of insight.', 'crystal', 55, 109),
('rutilated-quartz', 'Rutilated Quartz', 'Quartz (silicate)', 'SiO₂ with TiO₂ (rutile) needles', 'Clear with golden to reddish needles', '7', 'Bahia (Brazil), Madagascar', 'The golden ''hairs'' are rutile crystals that formed first and were later engulfed by the growing quartz.', 'Old European tradition called it ''Venus hair stone'', imagining the needles as the goddess''s golden locks.', 'crystal', 55, 110),
('smithsonite', 'Smithsonite', 'Carbonate', 'ZnCO₃', 'Pink, blue-green, yellow; botryoidal', '4–4.5', 'Kelly Mine, New Mexico (USA), Tsumeb (Namibia), Mexico', 'Named for James Smithson, founder of the Smithsonian; its pearly crusts come in pink, blue and green.', 'Crystal tradition calls smithsonite a gentle ''kindness stone'', a modern association with its soft colors.', 'crystal', 55, 111),
('stibnite', 'Stibnite', 'Sulfide', 'Sb₂S₃', 'Lead grey, metallic needles', '2', 'Xikuangshan (China), Romania, Ichinokawa (Japan)', 'Japan''s Ichinokawa mine produced sword-like stibnite crystals up to about 60 cm long.', 'Kohl made from stibnite lined ancient Egyptian eyes, worn by tradition to ward off the evil eye.', 'crystal', 55, 112),
('uvarovite', 'Uvarovite', 'Garnet (uvarovite)', 'Ca₃Cr₂(SiO₄)₃', 'Vivid emerald green druzy', '6.5–7.5', 'Ural Mountains (Russia), Outokumpu (Finland)', 'The rarest of the common garnets, uvarovite forms sparkling druzes of crystals usually too small to facet.', 'Named for a Russian count, it is gifted in crystal circles as a stone of abundance.', 'crystal', 55, 113),
('vanadinite', 'Vanadinite', 'Vanadate (apatite group)', 'Pb₅(VO₄)₃Cl', 'Bright red to orange-red', '3–4', 'Mibladen (Morocco), Arizona (USA)', 'Morocco''s Mibladen mines produce glossy red hexagonal crystals, and vanadinite is an ore of vanadium.', 'Crystal circles traditionally treat vanadinite as a stone of stamina, inspired by its fiery red.', 'crystal', 55, 114),
('amber', 'Amber', 'Organic gem (fossil resin)', 'Organic: fossilized tree resin', 'Honey yellow to cognac orange', '2–2.5', 'Baltic Sea coast, Dominican Republic, Myanmar', 'Baltic amber is tens of millions of years old and can preserve insects and plant fragments in perfect detail.', 'Greek myth says amber formed from the tears of the Heliades, mourning their brother Phaethon.', 'crystal', 50, 115),
('covellite', 'Covellite', 'Sulfide', 'CuS', 'Indigo blue with purple iridescence', '1.5–2', 'Butte, Montana (USA), Sardinia (Italy), Bor (Serbia)', 'Covellite was the first known natural superconductor, though only at temperatures near absolute zero.', 'Crystal folklore calls covellite a ''dream stone'', its indigo said to deepen reflection.', 'crystal', 50, 116),
('lake-superior-agate', 'Lake Superior Agate', 'Quartz (chalcedony)', 'SiO₂', 'Red, orange and white iron-stained bands', '6.5–7', 'Lake Superior region (USA, Canada)', 'Born in lava flows about 1.1 billion years old, these agates were spread by glaciers across the upper Midwest.', 'Minnesota made it the state gemstone in 1969, and beachcomber lore treats a first find as a sign of luck.', 'crystal', 50, 117),
('native-copper', 'Native Copper', 'Native element', 'Cu', 'Copper red, tarnishing brown or green', '2.5–3', 'Michigan (USA), Arizona (USA), Corocoro (Bolivia)', 'Michigan''s Keweenaw Peninsula held enormous masses of native copper, one weighing hundreds of tonnes.', 'Copper''s ancient link to Venus and Cyprus gave it a lasting tradition as the metal of love.', 'crystal', 50, 118),
('ocean-jasper', 'Ocean Jasper', 'Quartz (jasper)', 'SiO₂ (orbicular chalcedony)', 'Green, white and pink orb patterns', '6.5–7', 'Marovato (Madagascar)', 'Its orbs are radiating chalcedony spheres, and the classic coastal deposit can be reached only at low tide.', 'Madagascar''s seashore gave it a modern crystal tradition as a stone of joy and patience.', 'crystal', 50, 119),
('pyromorphite', 'Pyromorphite', 'Phosphate (apatite group)', 'Pb₅(PO₄)₃Cl', 'Grass green to yellow, barrel-shaped prisms', '3.5–4', 'Les Farges (France), Idaho (USA), Daoping (China)', 'Its name means ''fire form'': a melted bead of it recrystallizes into crystal faces as it cools.', 'Collectors traditionally link pyromorphite''s green to garden growth, calling it a nature stone.', 'crystal', 50, 120),
('rainbow-moonstone', 'Rainbow Moonstone', 'Feldspar (plagioclase)', '(Ca,Na)(Al,Si)₄O₈', 'Milky white with blue and rainbow sheen', '6–6.5', 'India, Madagascar, Sri Lanka', 'Despite the name, it is a white labradorite, not true moonstone, which is a potassium feldspar.', 'Indian tradition pairs it with moonstone as a lunar gem, a customary token of love.', 'crystal', 50, 121),
('seraphinite', 'Seraphinite', 'Chlorite (clinochlore)', '(Mg,Fe)₅Al(AlSi₃O₁₀)(OH)₈', 'Dark green with silvery feathery shimmer', '2–2.5', 'Lake Baikal region (Russia)', 'This Siberian clinochlore shows silvery, feather-like flashes as its mica-like flakes catch the light.', 'Named for the six-winged seraphim, it is traditionally linked to angelic guardianship.', 'crystal', 50, 122),
('agatized-coral', 'Agatized Coral', 'Quartz (chalcedony)', 'SiO₂ replacing fossil coral', 'Cream, pink and tan with flower-like polyp patterns', '6.5–7', 'Florida (USA), Indonesia', 'Ancient coral colonies were replaced by chalcedony, and Florida made agatized coral its state stone in 1979.', 'Collectors traditionally call its fossil polyp rosettes ''flowers of the sea''.', 'crystal', 45, 123),
('apophyllite', 'Apophyllite', 'Phyllosilicate (apophyllite group)', 'KCa₄Si₈O₂₀(F,OH)·8H₂O', 'Colorless to pale green', '4.5–5', 'Maharashtra (India), Brazil', 'Its name means ''to flake off'' in Greek, as it peels into thin layers when heated.', 'Crystal lore regards apophyllite pyramids as tools for meditation and mental clarity.', 'crystal', 45, 124),
('blue-chalcedony', 'Blue Chalcedony', 'Quartz (chalcedony)', 'SiO₂', 'Soft lavender-blue to sky blue', '6.5–7', 'Namibia, Turkey, Malawi', 'Chalcedony is quartz made of fibers too small to see, and its soft blue comes largely from scattered light.', 'In crystal folklore, blue chalcedony is said to soothe nerves and encourage gentle speech.', 'crystal', 45, 125),
('blue-lace-agate', 'Blue Lace Agate', 'Quartz (chalcedony)', 'SiO₂', 'Pale blue with white lacy bands', '6.5–7', 'Southern Namibia, Malawi', 'Classic blue lace agate came from a single deposit in southern Namibia, making old material a collector favorite.', 'Crystal tradition calls it a throat stone, said to help shy speakers find their voice.', 'crystal', 45, 126),
('celestite', 'Celestite', 'Sulfate', 'SrSO₄', 'Pale sky blue', '3–3.5', 'Madagascar, Ohio (USA), Sicily (Italy)', 'Celestite is a main source of strontium, and Ohio''s Crystal Cave formed inside a giant celestite geode.', 'Named from Latin ''caelestis'', heavenly, it is linked in crystal tradition to angelic realms.', 'crystal', 45, 127),
('hemimorphite', 'Hemimorphite', 'Sorosilicate', 'Zn₄Si₂O₇(OH)₂·H₂O', 'Sky blue to white, botryoidal or bladed', '4.5–5', 'Yunnan (China), Mexico, DR Congo', 'Its name means ''half shape'': the two ends of each crystal differ, a sign of its polar structure.', 'Crystal folklore says hemimorphite encourages self-reflection, honoring its two-faced crystals.', 'crystal', 45, 128),
('jet', 'Jet', 'Organic gem (fossil wood)', 'Organic: compacted fossil wood (lignite)', 'Deep velvety black', '2.5–4', 'Whitby (England), Asturias (Spain), Turkey', 'Whitby jet formed from Jurassic trees related to the monkey puzzle and boomed as Victorian mourning jewelry.', 'Queen Victoria wore jet while mourning Albert, and older folk tradition hung it in homes to ward off evil.', 'crystal', 45, 129),
('labradorite', 'Labradorite', 'Feldspar (plagioclase)', '(Ca,Na)(Al,Si)₄O₈', 'Grey to dark with blue, green and gold flash', '6–6.5', 'Labrador (Canada), Madagascar, Finland', 'Its flash, called labradorescence, comes from light interfering in microscopic layers inside the feldspar.', 'Inuit legend tells that the northern lights were trapped in Labrador''s rocks until a warrior freed most with his spear.', 'crystal', 45, 130),
('malachite', 'Malachite', 'Carbonate', 'Cu₂CO₃(OH)₂', 'Banded light and dark green', '3.5–4', 'DR Congo, Ural Mountains (Russia), Arizona (USA)', 'Ural malachite clad whole palace rooms in St. Petersburg, including the Malachite Room of the Winter Palace.', 'In crystal folklore, malachite is said to be a stone of transformation and a protector of travelers.', 'crystal', 45, 131),
('nuummite', 'Nuummite', 'Rock (metamorphic)', 'Rock: anthophyllite and gedrite amphiboles', 'Black with golden iridescent flashes', '5.5–6', 'Nuuk region (Greenland)', 'Found near Nuuk, Greenland, this metamorphic rock is around 3 billion years old and flashes gold from amphibole fibers.', 'Crystal lore calls nuummite the ''sorcerer''s stone'', a modern name for an ancient rock.', 'crystal', 45, 132),
('pink-opal', 'Pink Opal', 'Opal (common opal)', 'SiO₂·nH₂O', 'Soft pink, opaque', '5.5–6.5', 'Andes (Peru)', 'Unlike precious opal, Peruvian pink opal is common opal with no play-of-color, valued for its soft solid pink.', 'Crystal folklore calls pink opal a gentle heart stone, said to soothe old hurts.', 'crystal', 45, 133),
('rainbow-obsidian', 'Rainbow Obsidian', 'Volcanic glass', 'Volcanic glass with aligned microcrystals', 'Black with banded rainbow sheen', '5–5.5', 'Jalisco (Mexico)', 'Its rainbow bands appear when light strikes layers of tiny aligned mineral crystals within the glass.', 'Some crystal lore calls rainbow obsidian a gentle stone, hiding cheer beneath a dark surface.', 'crystal', 45, 134),
('ruby-in-zoisite', 'Ruby in Zoisite', 'Rock (metamorphic)', 'Rock: green zoisite with ruby (corundum) and hornblende', 'Green with pinkish-red ruby crystals', '6–9', 'Longido (Tanzania)', 'Called anyolite, from a Maasai word for green, it pairs opaque ruby crystals with green zoisite and black hornblende.', 'Crystal folklore says ruby in zoisite unites passion with patience, a modern pairing of its two colors.', 'crystal', 45, 135),
('tourmalinated-quartz', 'Tourmalinated Quartz', 'Quartz (silicate)', 'SiO₂ with black tourmaline (schorl) needles', 'Clear with black needle inclusions', '7', 'Minas Gerais (Brazil), Madagascar', 'Black needles of schorl tourmaline cut through the quartz, trapped as the host crystal grew around them.', 'Crystal folklore says it unites quartz''s clarity with tourmaline''s grounding, two stones in one.', 'crystal', 45, 136),
('variscite', 'Variscite', 'Phosphate', 'AlPO₄·2H₂O', 'Apple to bluish green with brown veins', '3.5–4.5', 'Utah (USA), Nevada (USA), Australia', 'Utah variscite is sometimes mistaken for turquoise, but it is an aluminum phosphate with no copper.', 'Crystal circles traditionally treat variscite as a worry stone, rubbed smooth for calm.', 'crystal', 45, 137),
('amazonite', 'Amazonite', 'Feldspar (microcline)', 'KAlSi₃O₈', 'Blue-green to turquoise', '6–6.5', 'Colorado (USA), Russia, Madagascar', 'Traces of lead and water in microcline give amazonite its color; no deposits are known along the Amazon.', 'Legend links it to the warrior Amazons, said to adorn their shields with the stone.', 'crystal', 40, 138),
('angelite', 'Angelite', 'Sulfate (anhydrite)', 'CaSO₄', 'Pale blue to lavender', '3.5', 'Peru', 'Angelite is a blue anhydrite, gypsum without its water, and it can slowly turn back to gypsum in damp air.', 'Its lore is recent: crystal circles adopted it in the late 20th century as a stone of calm and connection.', 'crystal', 40, 139),
('barite', 'Barite', 'Sulfate', 'BaSO₄', 'Colorless, golden, blue or white', '3–3.5', 'Morocco, Colorado (USA), Cumbria (England)', 'Barite is surprisingly heavy for a pale mineral; its name comes from the Greek ''barys'', heavy.', 'Oklahoma made barite roses its state rock, and local tradition gives them as rustic keepsakes.', 'crystal', 40, 140),
('bismuth', 'Bismuth', 'Native element', 'Bi', 'Silvery pink-white; rainbow oxide on lab crystals', '2–2.5', 'Bolivia, Saxony (Germany), Australia', 'The stepped rainbow ''hopper'' crystals sold widely are lab-grown from melted bismuth; their colors are a thin oxide film.', 'Saxon miners called it ''wismut'', and modern crystal lore links its staircase shapes to change.', 'crystal', 40, 141),
('bloodstone', 'Bloodstone', 'Quartz (chalcedony)', 'SiO₂', 'Dark green with red spots', '6.5–7', 'India, Australia, Brazil', 'Also called heliotrope, bloodstone is green chalcedony speckled with red spots of iron oxide.', 'Medieval Christian legend held that its red spots were drops of Christ''s blood fallen on green stone.', 'crystal', 40, 142),
('botswana-agate', 'Botswana Agate', 'Quartz (chalcedony)', 'SiO₂', 'Fine grey, pink and peach bands', '6.5–7', 'Bobonong (Botswana)', 'Formed in gas pockets of ancient basalt, its delicate pink-grey banding can run to hundreds of fine layers.', 'In crystal folklore Botswana agate is a ''sunset stone'', said to steady you through times of change.', 'crystal', 40, 143),
('chrysanthemum-stone', 'Chrysanthemum Stone', 'Rock (sedimentary)', 'Rock: celestite or calcite ''flowers'' in limestone', 'White flower patterns on dark grey rock', '3–3.5', 'Hunan (China), Japan, British Columbia (Canada)', 'Its white petals are radiating crystals, originally celestite often replaced by calcite, grown in dark limestone.', 'In China and Japan it is traditionally prized as a stone of good fortune, its blossoms evoking the chrysanthemum.', 'crystal', 40, 144),
('chrysocolla', 'Chrysocolla', 'Phyllosilicate (hydrated copper silicate)', '(Cu,Al)₂H₂Si₂O₅(OH)₄·nH₂O', 'Turquoise blue to green', '2–4', 'Arizona (USA), Peru, DR Congo', 'A soft copper silicate, chrysocolla''s name means ''gold glue'', after an ancient solder used for gold.', 'Crystal tradition links chrysocolla to calm communication and the peaceful energy of water.', 'crystal', 40, 145),
('crazy-lace-agate', 'Crazy Lace Agate', 'Quartz (chalcedony)', 'SiO₂', 'Cream, red, gold and grey swirling bands', '6.5–7', 'Chihuahua (Mexico)', 'Found in northern Mexico, its tightly folded, chaotic banding is also sold as ''Mexican lace agate''.', 'Nicknamed the ''laughter stone'', it is traditionally said to lift the spirit.', 'crystal', 40, 146),
('dendritic-agate', 'Dendritic Agate', 'Quartz (chalcedony)', 'SiO₂', 'Milky white with black fern-like dendrites', '6.5–7', 'India, Brazil', 'Its fern-like patterns are manganese oxide crystals that branched along tiny cracks; they are not fossils.', 'Victorian collectors cherished it as ''tree stone'', a keepsake said to hold tiny forests sealed inside.', 'crystal', 40, 147),
('epidote', 'Epidote', 'Sorosilicate', 'Ca₂(Al,Fe)₃(SiO₄)(Si₂O₇)O(OH)', 'Pistachio to dark green', '6–7', 'Pakistan, Knappenwand (Austria), Peru', 'Austria''s Knappenwand produced dark green epidote crystals widely regarded as the world''s finest.', 'Crystal lore links pistachio-green epidote to growth and the gathering of strength.', 'crystal', 40, 148),
('hawks-eye', 'Hawk''s Eye', 'Quartz (silicate)', 'SiO₂ with crocidolite fibers', 'Blue-grey with silky shifting bands', '7', 'Northern Cape (South Africa)', 'Hawk''s eye is tiger''s eye before oxidation: its blue-grey crocidolite fibers never altered to brown iron oxide.', 'Folk tradition names it for the far-seeing hawk, a stone said to sharpen perspective.', 'crystal', 40, 149),
('iceland-spar', 'Iceland Spar', 'Carbonate (calcite)', 'CaCO₃', 'Colorless, water-clear', '3', 'Helgustaðir (Iceland), Mexico, China', 'Iceland spar''s strong double refraction doubles any image seen through it, and it helped reveal polarized light.', 'Norse sagas mention a ''sunstone'' for finding the sun in clouds, and tradition says it was Iceland spar.', 'crystal', 40, 150),
('kyanite', 'Kyanite', 'Nesosilicate', 'Al₂SiO₅', 'Blue blades, also green or black', '4.5–7', 'Brazil, Nepal, Kenya', 'Kyanite''s hardness changes with direction: a knife scratches it along the blade but not across it.', 'A modern crystal belief holds that kyanite never needs cleansing, calling it ''self-clearing''.', 'crystal', 40, 151),
('okenite', 'Okenite', 'Silicate (hydrated calcium silicate)', 'Ca₁₀Si₁₈O₄₆·18H₂O', 'White, cotton-ball tufts', '4.5–5', 'Maharashtra (India)', 'Okenite forms soft, fur-like ''cotton balls'' of hair-thin fibers in the gas pockets of Indian basalt.', 'Named for naturalist Lorenz Oken, its snowball tufts are treated in crystal lore as stones of comfort.', 'crystal', 40, 152),
('petoskey-stone', 'Petoskey Stone', 'Fossil (coral)', 'Fossil coral (Hexagonaria) in calcite', 'Grey with hexagonal coral pattern', '3–4', 'Michigan (USA)', 'These fossil Hexagonaria corals lived in Devonian seas about 350 million years ago; they are Michigan''s state stone.', 'Michigan legend links the stone''s name to Chief Petosegay, whose name is said to mean ''rising sun''.', 'crystal', 40, 153),
('petrified-wood', 'Petrified Wood', 'Fossil (silicified wood)', 'SiO₂ (quartz, chalcedony) replacing wood', 'Brown, red, grey with wood grain', '6.5–7', 'Arizona (USA), Madagascar, Indonesia', 'Silica-rich water replaced wood cell by cell; logs in Arizona''s Petrified Forest are over 200 million years old.', 'A retold Navajo story says the stone logs are the bones of a giant slain long ago.', 'crystal', 40, 154),
('polychrome-jasper', 'Polychrome Jasper', 'Quartz (jasper)', 'SiO₂ with iron oxides', 'Red, brown, cream and mustard swirls', '6.5–7', 'Northwestern Madagascar', 'Found in Madagascar in the 2000s, its swirling desert colors come from iron oxides in the silica.', 'Called ''desert jasper'', it is linked in crystal circles to creativity and warmth.', 'crystal', 40, 155),
('prehnite', 'Prehnite', 'Phyllosilicate', 'Ca₂Al(AlSi₃O₁₀)(OH)₂', 'Pale apple to yellowish green', '6–6.5', 'Mali, Australia, South Africa', 'Named in 1788 for Dutch colonel Hendrik von Prehn, it is often cited as the first mineral named after a person.', 'Crystal folklore calls prehnite a ''stone of prophecy'', traditionally used to quiet the mind.', 'crystal', 40, 156),
('scolecite', 'Scolecite', 'Zeolite', 'CaAl₂Si₃O₁₀·3H₂O', 'Colorless to white, slender needles', '5–5.5', 'Maharashtra (India), Iceland', 'A zeolite from India''s basalts, its name comes from the Greek for ''worm'': heated, it curls like one.', 'Crystal tradition counts scolecite among calming stones, its radiating needles said to settle a busy mind.', 'crystal', 40, 157),
('septarian-nodule', 'Septarian Nodule', 'Rock (sedimentary concretion)', 'Rock: clay-rich concretion with calcite and aragonite', 'Grey-brown with yellow calcite veins', '3–4', 'Utah (USA), Madagascar, Morocco', 'Formed in seafloor mud millions of years ago, these nodules cracked and filled with yellow calcite in starry patterns.', 'Also called ''dragon stone'', septarian is said in crystal folklore to foster patience and calm speech.', 'crystal', 40, 158),
('smoky-quartz', 'Smoky Quartz', 'Quartz (silicate)', 'SiO₂', 'Light brown to nearly black', '7', 'Swiss Alps, Brazil, Colorado (USA)', 'Smoky quartz gets its color from natural radiation acting on traces of aluminum in the crystal.', 'Scottish tradition prizes smoky ''cairngorm'' quartz, set in kilt pins and dirk handles as Highland talismans.', 'crystal', 40, 159),
('staurolite', 'Staurolite', 'Nesosilicate', 'Fe₂Al₉Si₄O₂₃(OH)', 'Reddish brown to dark brown', '7–7.5', 'Georgia (USA), Virginia (USA), Russia', 'Its twin crystals cross at 60° or 90° to form natural X''s and crosses; it is Georgia''s state mineral.', 'Virginia legend says these ''fairy crosses'' formed from fairies'' tears on hearing of Christ''s death.', 'crystal', 40, 160),
('sulfur', 'Sulfur', 'Native element', 'S', 'Bright lemon yellow', '1.5–2.5', 'Sicily (Italy), Bolivia, Ijen (Indonesia)', 'Native sulfur forms around volcanic vents, and its crystals can crack from the warmth of a hand.', 'Called ''brimstone'' in old texts, it was traditionally burned to drive away evil and disease.', 'crystal', 40, 161),
('thunder-egg', 'Thunder Egg', 'Rock (volcanic nodule)', 'Rock: rhyolite shell with agate or chalcedony core', 'Brown shell with agate star core', '6.5–7', 'Oregon (USA), Germany, Queensland (Australia)', 'These rhyolite nodules hide star-shaped cores of agate, and Oregon named the thunder egg its state rock in 1965.', 'A retold Native American legend says thunder spirits hurled the eggs at one another in anger.', 'crystal', 40, 162),
('tiger-iron', 'Tiger Iron', 'Rock (banded iron formation)', 'Rock: tiger''s eye, red jasper and hematite', 'Banded gold, red and metallic grey', '5.5–7', 'Pilbara, Western Australia', 'A banded iron formation over 2 billion years old, its layers record ancient seas as oxygen built up on Earth.', 'Crystal folklore calls tiger iron a stone of stamina, three stones in one.', 'crystal', 40, 163),
('turritella-agate', 'Turritella Agate', 'Quartz (chalcedony)', 'SiO₂ replacing fossil snail shells', 'Dark brown with white spiral shell sections', '6.5–7', 'Wyoming (USA)', 'Despite the name, its fossils are freshwater Elimia snails, not marine Turritella, from Wyoming''s Green River Formation.', 'Fossil stones like this are traditionally kept by collectors as links to ancient life and deep time.', 'crystal', 40, 164),
('aragonite', 'Aragonite', 'Carbonate', 'CaCO₃', 'Orange-brown, white or blue; star-like clusters', '3.5–4', 'Morocco, Aragón (Spain), Mexico', 'Aragonite shares calcite''s formula but not its structure, and mollusks build shells and pearls from it.', 'Named for Spain''s Aragón, its starry ''sputnik'' clusters are kept as grounding stones in crystal tradition.', 'crystal', 35, 165),
('black-tourmaline', 'Black Tourmaline', 'Tourmaline (schorl)', 'NaFe₃Al₆(Si₆O₁₈)(BO₃)₃(OH)₃(OH)', 'Jet black, striated prisms', '7–7.5', 'Brazil, Pakistan, Erongo (Namibia)', 'Schorl is the most common tourmaline; its long, striated prisms have a rounded triangular cross section.', 'Crystal lore holds black tourmaline as a protective stone, traditionally placed by doorways.', 'crystal', 35, 166),
('bornite', 'Bornite', 'Sulfide', 'Cu₅FeS₄', 'Coppery bronze tarnishing purple-blue', '3', 'Butte, Montana (USA), Chile, Mexico', 'Fresh bornite is bronze, but it quickly tarnishes purple and blue, earning the nickname ''peacock ore''.', 'Crystal folklore calls bornite a ''happiness stone'', inspired by its peacock colors.', 'crystal', 35, 167),
('carnelian', 'Carnelian', 'Quartz (chalcedony)', 'SiO₂', 'Orange to red-orange', '6.5–7', 'India, Brazil, Uruguay', 'Iron oxide colors carnelian; Indus Valley artisans drilled and etched carnelian beads over 4,000 years ago.', 'Ancient Egyptians placed carnelian amulets with the dead, meant to ease the journey to the afterlife.', 'crystal', 35, 168),
('chalcopyrite', 'Chalcopyrite', 'Sulfide', 'CuFeS₂', 'Brassy yellow, tarnishing iridescent', '3.5–4', 'Peru, Mexico, China', 'The most important copper ore, it is softer and yellower than pyrite and tarnishes to iridescent blues and purples.', 'Alchemists saw its brassy sheen as a hint of hidden gold, another ''fool''s gold'' of old tradition.', 'crystal', 35, 169),
('chiastolite', 'Chiastolite', 'Nesosilicate (andalusite variety)', 'Al₂SiO₅ with carbon inclusions', 'Grey-brown with a dark cross pattern', '6.5–7.5', 'China, Spain, Australia', 'Carbonaceous inclusions in andalusite crystals line up as a dark cross, seen when a crystal is sliced across.', 'Tradition says pilgrims to Santiago de Compostela carried chiastolite crosses as protective tokens.', 'crystal', 35, 170),
('clear-quartz', 'Clear Quartz', 'Quartz (silicate)', 'SiO₂', 'Colorless, water-clear', '7', 'Arkansas (USA), Brazil, Madagascar', 'Quartz is piezoelectric: squeezed, it produces a voltage, which is why quartz crystals keep time in watches.', 'Ancient Greeks thought clear quartz was ice frozen so hard it could never thaw; krystallos means ice.', 'crystal', 35, 171),
('desert-rose', 'Desert Rose', 'Sulfate (gypsum)', 'CaSO₄·2H₂O with sand grains', 'Sandy tan rosettes', '2', 'Tunisia, Algeria, Chihuahua (Mexico)', 'These rosettes form as gypsum crystallizes in damp desert sand, trapping grains between its bladed petals.', 'In crystal folklore, desert rose helps one let go of old patterns, as the sand shapes the petals.', 'crystal', 35, 172),
('fluorite', 'Fluorite', 'Halide', 'CaF₂', 'Purple, green, blue, yellow, often banded', '4', 'China, Mexico, Weardale (England)', 'Fluorite gave its name to fluorescence, and many specimens glow blue-violet under ultraviolet light.', 'Some crystal circles call fluorite the ''genius stone'', a tradition linking it to order and focus.', 'crystal', 35, 173),
('galena', 'Galena', 'Sulfide', 'PbS', 'Silvery lead grey, cubic', '2.5–2.75', 'Missouri (USA), Madan (Bulgaria), Peru', 'The chief ore of lead, galena breaks into perfect cubes and served as the detector in early ''crystal'' radios.', 'Alchemical tradition tied lead to Saturn, and crystal lore now calls galena a grounding stone.', 'crystal', 35, 174),
('larvikite', 'Larvikite', 'Rock (igneous)', 'Rock: mostly feldspar (monzonite)', 'Dark grey with silvery-blue flashes', '6–6.5', 'Larvik (Norway)', 'This Norwegian igneous rock, Norway''s national stone, is polished worldwide for building facades.', 'Crystal folklore nicknames it ''Norwegian moonstone'', a stone traditionally tied to intuition.', 'crystal', 35, 175),
('lepidolite', 'Lepidolite', 'Mica', 'K(Li,Al)₃(Si,Al)₄O₁₀(F,OH)₂', 'Lilac to rose-violet, sparkly', '2.5–3.5', 'Minas Gerais (Brazil), Madagascar, California (USA)', 'A lithium-rich mica, lepidolite is an ore of lithium, and its name means ''scale stone'' in Greek.', 'Crystal folklore calls lepidolite a ''peace stone'', traditionally kept close in stressful times.', 'crystal', 35, 176),
('lodestone', 'Lodestone', 'Oxide (magnetite)', 'Fe₃O₄', 'Black, metallic', '5.5–6.5', 'Magnet Cove, Arkansas (USA), Sweden, Elba (Italy)', 'Lodestone is naturally magnetized magnetite, possibly by lightning; early compasses used it to find north.', 'Ancient lore tells of the shepherd Magnes, whose iron-nailed sandals stuck to a lodestone on Mount Ida.', 'crystal', 35, 177),
('mookaite', 'Mookaite', 'Quartz (jasper)', 'SiO₂ (silicified radiolarite)', 'Mustard yellow, red, purple and cream', '6.5–7', 'Mooka Creek, Western Australia', 'A silicified radiolarite, mookaite is built from the microscopic shells of ancient marine plankton.', 'Named for Mooka Creek, it carries a modern crystal tradition as a stone of adventure.', 'crystal', 35, 178),
('moss-agate', 'Moss Agate', 'Quartz (chalcedony)', 'SiO₂', 'Clear to milky with green moss-like inclusions', '6.5–7', 'India, Montana (USA), Brazil', 'The ''moss'' is not plant life but branching inclusions of green chlorite or iron and manganese minerals.', 'Long known as the gardener''s stone, folk tradition says moss agate brings good harvests.', 'crystal', 35, 179),
('picture-jasper', 'Picture Jasper', 'Quartz (jasper)', 'SiO₂ with iron oxides', 'Tan and brown with landscape-like patterns', '6.5–7', 'Oregon (USA), Idaho (USA), South Africa', 'Silica-rich mud and volcanic ash hardened into scenes of hills and skies, prized for ''landscape'' cabochons.', 'Folk tradition calls picture jasper Earth''s storybook, a stone for remembering the past.', 'crystal', 35, 180),
('pyrite', 'Pyrite', 'Sulfide', 'FeS₂', 'Brassy pale gold, metallic', '6–6.5', 'Navajún (Spain), Huanzala (Peru), Elba (Italy)', 'Spain''s Navajún mines yield near-perfect natural cubes; ''fool''s gold'' throws sparks when struck against steel.', 'Its name means ''fire'' in Greek, and modern folk tradition keeps pyrite on desks as a stone of abundance.', 'crystal', 35, 181),
('rhodonite', 'Rhodonite', 'Pyroxenoid (inosilicate)', '(Mn,Fe,Mg,Ca)SiO₃', 'Pink to rose red with black veins', '5.5–6.5', 'Ural Mountains (Russia), Broken Hill (Australia), Peru', 'Its name comes from the Greek ''rhodon'', rose; Ural rhodonite was carved for the Russian imperial court.', 'Crystal lore calls rhodonite a ''rescue stone'', said to bring calm in emotional storms.', 'crystal', 35, 182),
('rose-quartz', 'Rose Quartz', 'Quartz (silicate)', 'SiO₂', 'Pale to medium pink', '7', 'Brazil, Madagascar, South Dakota (USA)', 'Rose quartz is usually massive; its pink is linked to microscopic fibers of a dumortierite-like mineral.', 'Crystal folklore names rose quartz the stone of unconditional love, tied in retellings to Aphrodite.', 'crystal', 35, 183),
('shungite', 'Shungite', 'Rock (carbon-rich)', 'Rock: largely noncrystalline carbon with silicates', 'Matte to glossy black', '3.5–4', 'Karelia (Russia)', 'Found near Lake Onega in Karelia, this carbon-rich rock is about 2 billion years old.', 'Karelian tradition credits Peter the Great with founding a spa at nearby springs to refresh his soldiers.', 'crystal', 35, 184),
('stilbite', 'Stilbite', 'Zeolite', 'NaCa₄(Si₂₇Al₉)O₇₂·28H₂O', 'Peach to white bow-tie sheaves', '3.5–4', 'Maharashtra (India), Iceland, Brazil', 'Stilbite grows in wheat-sheaf or bow-tie bundles inside gas pockets of India''s Deccan basalt.', 'Crystal folklore regards stilbite as a gentle travel stone, said to ease the journey.', 'crystal', 35, 185),
('tigers-eye', 'Tiger''s Eye', 'Quartz (silicate)', 'SiO₂ with altered crocidolite fibers and iron oxides', 'Golden brown with silky shifting bands', '7', 'Northern Cape (South Africa), Western Australia', 'Its rolling silky shine comes from quartz grown around fine, parallel crocidolite fibers altered to iron oxides.', 'Roman soldiers are said to have carried engraved tiger''s eye for courage and protection in battle.', 'crystal', 35, 186),
('apache-tears', 'Apache Tears', 'Volcanic glass', 'Amorphous volcanic glass (obsidian nodules)', 'Translucent black to smoky brown', '5–5.5', 'Arizona (USA), New Mexico (USA)', 'These small obsidian nodules weather out of perlite; held up to light, they glow translucent smoky brown.', 'Legend tells that the tears of Apache women mourning fallen warriors turned to stone where they fell.', 'crystal', 30, 187),
('fuchsite', 'Fuchsite', 'Mica (muscovite variety)', 'K(Al,Cr)₂(AlSi₃O₁₀)(OH)₂', 'Sparkly emerald green', '2–3', 'Brazil, India, Zimbabwe', 'Chromium turns this muscovite mica green, and it is the glitter inside green aventurine.', 'Crystal tradition names fuchsite a ''healer''s helper'', a modern folk belief tied to its green glow.', 'crystal', 30, 188),
('green-aventurine', 'Green Aventurine', 'Quartz (quartzite)', 'SiO₂ with fuchsite (mica) flakes', 'Light to medium green with glittery spangles', '6.5–7', 'India, Brazil, Russia', 'Its shimmer, called aventurescence, comes from tiny flakes of green chromium-bearing mica.', 'Nicknamed the ''gambler''s stone'', green aventurine is traditionally carried for luck in games of chance.', 'crystal', 30, 189),
('hematite', 'Hematite', 'Oxide', 'Fe₂O₃', 'Metallic steel grey; red streak', '5.5–6.5', 'Brazil, Cumbria (England), Michigan (USA)', 'Polished hematite looks silver-black, yet it leaves a blood-red streak; its name comes from the Greek for blood.', 'Legend says Roman soldiers rubbed hematite on their bodies, believing it made them invincible.', 'crystal', 30, 190),
('howlite', 'Howlite', 'Borosilicate', 'Ca₂B₅SiO₉(OH)₅', 'White with grey to black web veins', '3–3.5', 'California (USA), Nova Scotia (Canada), Turkey', 'Porous howlite takes dye easily and is often dyed blue to imitate turquoise.', 'Crystal folklore holds howlite a calming stone, traditionally tucked under pillows for restful sleep.', 'crystal', 30, 191),
('obsidian', 'Obsidian', 'Volcanic glass', 'Amorphous silica-rich volcanic glass', 'Glossy black', '5–5.5', 'Mexico, Armenia, Oregon (USA)', 'Obsidian forms when lava cools too fast to crystallize; a freshly fractured edge can be sharper than a steel scalpel.', 'Aztec priests polished obsidian into mirrors, a tradition tied to the god Tezcatlipoca, ''Smoking Mirror''.', 'crystal', 30, 192),
('onyx', 'Onyx', 'Quartz (chalcedony)', 'SiO₂', 'Black and white parallel bands', '6.5–7', 'Brazil, India, Uruguay', 'True onyx is banded chalcedony; much ''black onyx'' sold today is chalcedony dyed with a sugar-and-acid treatment.', 'From the Greek for fingernail, legend says Cupid trimmed sleeping Venus''s nails and the gods turned them to stone.', 'crystal', 30, 193),
('orange-calcite', 'Orange Calcite', 'Carbonate (calcite)', 'CaCO₃', 'Pale to vivid orange', '3', 'Chihuahua (Mexico), Brazil', 'Calcite fizzes in weak acid and defines 3 on the Mohs scale; traces of iron give this variety its orange.', 'Crystal folklore calls orange calcite a stone of creative spark and playful energy.', 'crystal', 30, 194),
('red-jasper', 'Red Jasper', 'Quartz (jasper)', 'SiO₂ with iron oxide (hematite)', 'Brick red to deep red', '6.5–7', 'India, South Africa, Brazil', 'Jasper is opaque microcrystalline quartz packed with impurities; hematite gives red jasper its color.', 'Ancient Egyptians carved red jasper into the tyet amulet, associated with the goddess Isis.', 'crystal', 30, 195),
('selenite', 'Selenite', 'Sulfate (gypsum)', 'CaSO₄·2H₂O', 'Colorless to white, transparent', '2', 'Naica (Mexico), Morocco, Utah (USA)', 'Mexico''s Naica Cave of the Crystals holds selenite beams over 11 m long, among the largest crystals known.', 'Named for Selene, the Greek moon goddess, it is traditionally kept as a cleansing ''moon stone''.', 'crystal', 30, 196),
('serpentine', 'Serpentine', 'Serpentine group (phyllosilicate)', '(Mg,Fe)₃Si₂O₅(OH)₄', 'Yellow-green to dark green, mottled', '2.5–6', 'Afghanistan, China, California (USA)', 'Named for its snakeskin-like mottling, serpentine forms when olivine-rich rock reacts with water underground.', 'Medieval lore held that serpentine protected its bearer from snakebite and poison.', 'crystal', 30, 197),
('snowflake-obsidian', 'Snowflake Obsidian', 'Volcanic glass', 'Volcanic glass with cristobalite', 'Black with white ''snowflake'' patches', '5–5.5', 'Utah (USA), Mexico', 'The snowflakes are radial clusters of cristobalite, a form of silica that grew as the glass slowly devitrified.', 'Crystal tradition calls it a stone of balance, its pale flakes like light in darkness.', 'crystal', 30, 198),
('sodalite', 'Sodalite', 'Feldspathoid (sodalite group)', 'Na₈(Al₆Si₆O₂₄)Cl₂', 'Royal blue with white veins', '5.5–6', 'Bahia (Brazil), Ontario (Canada), Namibia', 'Often mistaken for lapis, sodalite seldom holds pyrite and usually shows white veins of other minerals.', 'Crystal tradition calls sodalite a ''poet''s stone'', said to unite logic and expression.', 'crystal', 30, 199),
('unakite', 'Unakite', 'Rock (altered granite)', 'Rock: pink feldspar, green epidote, quartz', 'Pink and olive green mottled', '6–7', 'North Carolina (USA), Virginia (USA), South Africa', 'Named for the Unaka Mountains of North Carolina and Tennessee, unakite is granite altered by epidote.', 'Crystal tradition calls unakite a stone of partnership, its pink and green growing together.', 'crystal', 30, 200);--> statement-breakpoint
